102	mod tests {
103	    use serde_json::json;
104	
105	    use super::validate_request_compat;
106	    use crate::routes::openai::completions::types::CompletionRequest;
107	
108	    fn base_request() -> CompletionRequest {
109	        serde_json::from_value(json!({
110	            "model": "Qwen/Qwen1.5-0.5B-Chat",
111	            "prompt": "hello",
112	            "stream": true,
113	        }))
114	        .expect("parse request")
115	    }
116	
117	    fn served_names(names: &[&str]) -> Vec<String> {
118	        names.iter().map(|s| s.to_string()).collect()
119	    }
120	
121	    #[test]
122	    fn validate_request_compat_accepts_logprobs() {
123	        let request = CompletionRequest {
124	            logprobs: Some(1),
125	            ..base_request()
126	        };
127	        assert!(
128	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_ok()
129	        );
130	    }
131	
132	    #[test]
133	    fn validate_request_compat_accepts_any_served_name() {
134	        let request = base_request();
135	        assert!(
136	            validate_request_compat(
137	                &request,
138	                &served_names(&["other-alias", "Qwen/Qwen1.5-0.5B-Chat"])
139	            )
140	            .is_ok()
141	        );
142	    }
143	
144	    #[test]
145	    fn validate_request_compat_rejects_unknown_model() {
146	        let request = base_request();
147	        assert!(validate_request_compat(&request, &served_names(&["other-model"])).is_err());
148	    }
149	
150	    #[test]
151	    fn validate_request_compat_rejects_streaming_prompt_logprobs() {
152	        let request = CompletionRequest {
153	            prompt_logprobs: Some(1),
154	            ..base_request()
155	        };
156	        assert!(
157	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_err()
158	        );
159	    }
160	
161	    #[test]
162	    fn validate_request_compat_accepts_non_stream_prompt_logprobs() {
163	        let request = CompletionRequest {
164	            stream: false,
165	            prompt_logprobs: Some(-1),
166	            ..base_request()
167	        };
168	        assert!(
169	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_ok()
170	        );
171	    }
172	
173	    #[test]
174	    fn validate_request_compat_accepts_prompt_only_echo() {
175	        let request = CompletionRequest {
176	            stream: false,
177	            echo: true,
178	            max_tokens: Some(0),
179	            ..base_request()
180	        };
181	        assert!(
182	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_ok()
183	        );
184	    }
185	
186	    #[test]
187	    fn validate_request_compat_rejects_prompt_only_without_echo() {
188	        let request = CompletionRequest {
189	            stream: false,
190	            echo: false,
191	            max_tokens: Some(0),
192	            ..base_request()
193	        };
194	        assert!(
195	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_err()
196	        );
197	    }
198	}
