26	impl ApiError {
27	    /// Return the HTTP status code associated with this API error.
28	    pub fn status_code(&self) -> StatusCode {
29	        match self {
30	            Self::InvalidRequest { .. } => StatusCode::BAD_REQUEST,
31	            Self::ModelNotFound { .. } => StatusCode::NOT_FOUND,
32	            Self::ServerError { .. } => StatusCode::INTERNAL_SERVER_ERROR,
33	            Self::JsonParseError { .. } => StatusCode::BAD_REQUEST,
